#pragma once
#include <Arduino.h>
#include <pgmspace.h>

// Teco pequeno para los minijuegos

#define MINI_TRANSPARENT 0xF81F

#ifndef MINI_SPRITE_DEFINED
#define MINI_SPRITE_DEFINED
// sprite comprimido: cada pixel es 1 byte (indice en su paleta propia)
struct MiniSprite {
  const uint8_t* px;
  const uint16_t* pal;
  uint8_t w;
  uint8_t h;
};

// color del pixel i del sprite
static inline uint16_t miniPx(const MiniSprite* s, int i) {
  return pgm_read_word(&s->pal[pgm_read_byte(&s->px[i])]);
}
#endif

